    if (headerPart == null || headerPart.isEmpty()) {
        return -1;
    }
    int len = headerPart.length();
    if (end < 0) {
        end = 0;
    }
    if (end >= len) {
        return -1;
    }
    int idx = headerPart.indexOf("\r\n", end);
    return idx == -1 ? -1 : idx;
}

