private int parseEndOfLine(String headerPart, int end) {
    // Validate input parameters
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart cannot be null");
    }
    int len = headerPart.length();
    if (end < 0 || end > len) {
        throw new IllegalArgumentException("end index is out of bounds");
    }

    // Find the first CRLF sequence starting from 'end'
    for (int i = end; i < len - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i; // Return the index of the start of \r\n
        }
    }

    // Return -1 if no end-of-line sequence is found
    return -1;
}

private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null) {
        return -1;
    }
    if (end < 0) {
        return -1;
    }
    int len = headerPart.length();
    // The sequence to look for is "\r\n". We need at least two characters to match.
    for (int i = Math.max(0, end); i < len - 1; i++) {
        char c = headerPart.charAt(i);
        if (c == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    return -1;
}

