public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    try {
        // Attempt to use a convenient factory method if available
        return IsomorphicGraphMapping.createIdentity(graph);
    } catch (NoSuchMethodError | NoSuchMethodException ignored) {
        // Fallback: construct mapping manually
        IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>(graph, graph);
        for (V vertex : graph.getVertices()) {
            // Map each vertex to itself
            mapping.setVertexMapping(vertex, vertex);
        }
        for (E edge : graph.getEdges()) {
            // Map each edge to itself
            mapping.setEdgeMapping(edge, edge);
        }
        return mapping;
    } catch (Exception e) {
