public static <V,E>IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    if (graph == null){
        throw new IllegalArgumentException("graph must not be null");
    }
    java.util.Map<V,V> vertexMap = new java.util.HashMap<>();
    for (V v : graph.vertexSet()){
        vertexMap.put(v, v);
    }
    java.util.Map<E,E> edgeMap = new java.util.HashMap<>();
    for (E e : graph.edgeSet()){
        edgeMap.put(e, e);
    }
    return new IsomorphicGraphMapping<V,E>(){
        @Override
        public V mapVertex(V vertex){
            return vertexMap.get(vertex);
        }
        @Override
        public E mapEdge(E edge){
            return edgeMap.get(edge);
        }
        @Override
        public boolean containsMappedVertex(V vertex){
            return vertexMap.containsKey(vertex);
        }
        @Override
        public boolean containsMappedEdge(E edge){
            return edgeMap.containsKey(edge);
        }
        @Override
        public java.util.Set<V> getMappedVertexSet(){
            return vertexMap.keySet();
        }
        @Override
        public java.util.Set<E> getMappedEdgeSet(){
            return edgeMap.keySet();
        }
    };
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file");
    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }
    java.util.Deque<java.io.File> stack = new java.util.ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        java.io.File f = stack.pop();
        if (f.isDirectory()) {
            java.io.File[] children = f.listFiles();
            if (children != null) {
                for (java.io.File child : children) {
                    stack.push(child);
                }
            }
        }
        f.deleteOnExit();
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
