    }
    java.util.List<File> toDelete = new java.util.ArrayList<>();
    java.util.Deque<File> stack = new java.util.ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File curr = stack.pop();
        if (curr.isDirectory()) {
            File[] children = curr.listFiles();
            if (children != null) {
                for (File child : children) {
                    stack.push(child);
                }
            }
        }
        toDelete.add(curr);
    }
    java.util.Collections.reverse(toDelete);
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        for (File f : toDelete) {
            try {
                java.nio.file.Files.deleteIfExists(f.toPath());
            } catch (IOException e) {
                // Ignore deletion failures during shutdown
            }
        }
    }));
}

