@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        return;
    }
    // Add all vertices from the map to the target graph
    for (V vertex : resultMap.values()) {
        if (vertex == null) {
            continue;
        }
        if (!target.containsVertex(vertex)) {
            target.addVertex(vertex);
        }
    }

    // Build a list of vertices in insertion order
    List<V> vertices = new ArrayList<>(resultMap.values());
    if (vertices.size() < 2) {
        return; // Not enough vertices for a bipartite graph
    }

    // Partition the vertices into two sets arbitrarily (e.g., by odd/even indices)
    List<V> leftSet = new ArrayList<>();
    List<V> rightSet = new ArrayList<>();
    for (int i = 0; i < vertices.size(); i++) {
        V v = vertices.get(i);
        if (v == null) {
            continue;
        }
        if (i % 2 == 0) {
            leftSet.add(v);
        } else {
            rightSet.add(v);
        }
    }

    // Create all possible edges between leftSet and rightSet
    for (V u : leftSet) {
        for (V v : rightSet) {
            if (u == null || v == null || u.equals(v)) {
                continue;
            }
            // Add edge only if it does not already exist
            if (!target.containsEdge(u, v)) {
                target.addEdge(u, v);
            }
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if (target == null || resultMap == null) {
        return;
    }
    // Partition vertices into two sets for a bipartite graph
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    int half = resultMap.size() / 2;
    int count = 0;
    for (V vertex : resultMap.values()) {
        if (vertex == null) {
            continue; // skip nulls
        }
        target.addVertex(vertex);
        if (count < half) {
            left.add(vertex);
        } else {
            right.add(vertex);
        }
        count++;
    }
    // Connect each vertex in the left set to every vertex in the right set
    for (V u : left) {
        for (V v : right) {
            // Avoid adding self-loop if both sets share a vertex (shouldn't happen in strict bipartite)
            if (!u.equals(v)) {
                target.addEdge(u, v);
            }
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if(target == null || resultMap == null){
        return;
    }
    // Add all vertices to the graph
    for(V v : resultMap.values()){
        if(v != null){
            target.addVertex(v);
        }
    }
    // No edges to create if fewer than 2 vertices
    if(resultMap.size() < 2){
        return;
    }
    // Split the vertices into two groups for the bipartite sets
    List<V> vertices = new ArrayList<>(resultMap.values());
    int mid = vertices.size() / 2;
    List<V> left = vertices.subList(0, mid);
    List<V> right = vertices.subList(mid, vertices.size());
    // Add a complete set of edges between the two partitions
    for(V l : left){
        for(V r : right){
            if(l != null && r != null){
                // In most graph APIs, addEdge automatically constructs an edge instance
                target.addEdge(l, r);
            }
        }
    }
}

@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("target and resultMap must not be null");
    }
    // Ensure the graph is empty before populating
    for (V vertex : new java.util.ArrayList<V>(target.getVertices())) {
        target.removeVertex(vertex);
    }
    // Collect all vertices from the map
    java.util.List<V> vertices = new java.util.ArrayList<V>(resultMap.values());
    int total = vertices.size();
    // Split vertices into two partitions for a complete bipartite graph
    int mid = total / 2;
    // Add all vertices to the graph
    for (V v : vertices) {
        target.addVertex(v);
    }
    // Connect every vertex from the first partition to every vertex in the second
    for (int i = 0; i < mid; i++) {
        V left = vertices.get(i);
        for (int j = mid; j < total; j++) {
            V right = vertices.get(j);
            target.addEdge(left, right);
        }
    }
}

