public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream cannot be null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema cannot be null");
    }
    if (message == null) {
        throw new NullPointerException("Message cannot be null");
    }
    // Calculate the serialized size of the message
    int messageSize = schema.getSerializedSize(message);
    // Create a CodedOutputStream for easier varint handling
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    // Write the length prefix as a varint
    cos.writeRawVarint32(messageSize);
    // Serialize the message itself
    schema.write(message, cos);
    cos.flush();
    return messageSize;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    // Determine the serialized size of the message
    int size = schema.getSerializedSize(message);
    // Prefix the output with the size (big‑endian)
    DataOutputStream dos = new DataOutputStream(out);
    dos.writeInt(size);
    // Write the serialized message
    schema.writeTo(message, out);
    // Flush if the stream supports it
    if (out instanceof Flushable) {
        ((Flushable) out).flush();
    }
    return size;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    int size = schema.getEncodedSize(message, buffer);
    int tmp = size;
    while ((tmp & ~0x7F) != 0) {
        out.write((tmp & 0x7F) | 0x80);
        tmp >>>= 7;
    }
    out.write(tmp);
    schema.write(message, out);
    return size;
}

