public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) return null;
    if (!(genericType instanceof ParameterizedType)) return null;
    ParameterizedType ptype = (ParameterizedType) genericType;
    Type[] typeArgs = ptype.getActualTypeArguments();
    // Build a map from type variables declared by targetType's supertypes/interfaces to actual types.
    Map<TypeVariable<?>, Type> varMap = new java.util.HashMap<>();
    Class<?> clazz = targetType;
    while (clazz != null) {
        // Superclass
        Type superType = clazz.getGenericSuperclass();
        if (superType instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) superType;
            TypeVariable<?>[] vars = ((Class<?>) pt.getRawType()).getTypeParameters();
            Type[] args = pt.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                if (!varMap.containsKey(vars[i])) varMap.put(vars[i], args[i]);
            }
        }
        // Interfaces
        for (Type iface : clazz.getGenericInterfaces()) {
            if (iface instanceof ParameterizedType) {
                ParameterizedType pt = (ParameterizedType) iface;
                TypeVariable<?>[] vars = ((Class<?>) pt.getRawType()).getTypeParameters();
                Type[] args = pt.getActualTypeArguments();
                for (int i = 0; i < vars.length; i++) {
                    if (!varMap.containsKey(vars[i])) varMap.put(vars[i], args[i]);
                }
            }
        }
        clazz = clazz.getSuperclass();
    }
    Class<?>[] result = new Class<?>[typeArgs.length];
    for (int i = 0; i < typeArgs.length; i++) {
        Type t = typeArgs[i];
        // Resolve type variables using the collected mapping.
        while (t instanceof TypeVariable && varMap.containsKey(t)) {
            Type resolved = varMap.get(t);
            if (resolved == t) break; // Avoid infinite loop if same variable
            t = resolved;
        }
        if (t instanceof Class) {
            result[i] = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            result[i] = (Class<?>) ((ParameterizedType) t).getRawType();
        } else if (t instanceof java.lang.reflect.WildcardType) {
            // For wildcards we attempt to use the upper bound if available
            Type[] upperBounds = ((java.lang.reflect.WildcardType) t).getUpperBounds();
            if (upperBounds.length == 1 && upperBounds[0] instanceof Class) {
                result[i] = (Class<?>) upperBounds[0];
            } else {
                return null;
            }
        } else {
            return null; // Unresolvable type argument
        }
    }
    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pGeneric = (ParameterizedType) genericType;
    Type raw = pGeneric.getRawType();
    if (!(raw instanceof Class<?>)) {
        return null;
    }
    Class<?> rawClass = (Class<?>) raw;

    // Find the candidate type in targetType hierarchy that matches rawClass
    Type candidateType = null;
    // Check direct superclass
    Type superType = targetType.getGenericSuperclass();
    if (superType instanceof ParameterizedType) {
        ParameterizedType ps = (ParameterizedType) superType;
        if (ps.getRawType().equals(rawClass)) {
            candidateType = ps;
        }
    }
    // If not found, check interfaces
    if (candidateType == null) {
        for (Type intf : targetType.getGenericInterfaces()) {
            if (intf instanceof ParameterizedType) {
                ParameterizedType pi = (ParameterizedType) intf;
                if (pi.getRawType().equals(rawClass)) {
                    candidateType = pi;
                    break;
                }
            }
        }
    }
    if (candidateType == null) {
        return null; // could not find matching type in hierarchy
    }

    Type[] genericArgs = pGeneric.getActualTypeArguments();
    Type[] concreteArgs = ((ParameterizedType) candidateType).getActualTypeArguments();
    TypeVariable<?>[] rawParams = rawClass.getTypeParameters();
    Class<?>[] result = new Class<?>[genericArgs.length];

    for (int i = 0; i < genericArgs.length; i++) {
        Type arg = genericArgs[i];
        if (arg instanceof Class<?>) {
            result[i] = (Class<?>) arg;
        } else if (arg instanceof TypeVariable<?>) {
            TypeVariable<?> tv = (TypeVariable<?>) arg;
            int idx = -1;
            for (int j = 0; j < rawParams.length; j++) {
                if (rawParams[j].equals(tv)) {
                    idx = j;
                    break;
                }
            }
            if (idx == -1) {
                return null;
            }
            Type concrete = concreteArgs[idx];
            if (concrete instanceof Class<?>) {
                result[i] = (Class<?>) concrete;
            } else if (concrete instanceof ParameterizedType) {
                result[i] = (Class<?>) ((ParameterizedType) concrete).getRawType();
            } else {
                return null; // couldn't resolve to a concrete class
            }
        } else {
            return null; // unknown type (WildcardType, GenericArrayType, etc.)
        }
    }
    return result;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null || !(genericType instanceof ParameterizedType)) {
