protected List<TimeRange> buildTimeRanges(long start, long end){
    // Ensure the duration constant is positive to avoid infinite loops
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be a positive value");
    }
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges; // empty list for invalid or zero-length interval
    }
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long chunkSize = FETCH_DATA_DURATION;
    if (chunkSize <= 0) {
        throw new IllegalStateException("FETCH_DATA_DURATION must be greater than zero");
    }
    long current = start;
    while (current < end) {
        long next = Math.min(current + chunkSize, end);
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

