            next = currentStart + FETCH_DATA_DURATION;
            if (next > end) {
                next = end;
            }
        }
        ranges.add(new TimeRange(currentStart, next));
        currentStart = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<>();
    if(start >= end){
        return ranges;
    }
    long current = start;
    while(current < end){
        long chunk = Math.min(FETCH_DATA_DURATION, end - current);
        ranges.add(new TimeRange(current, current + chunk));
        current += chunk;
    }
    return ranges;
}

