static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0) {
        return timeBucket;
    }
    long year = timeBucket / 10000L;
    long month = (timeBucket / 100L) % 100L;
    long day = timeBucket % 100L;
    long bucketDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + bucketDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if (timeBucket <= 0) {
        return 0L;
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    // Compute the start day of the bucket the given day falls into
    int bucketDay = 1 + ((day - 1) / dayStep) * dayStep;

    // Adjust bucketDay if it exceeds the maximum day of the month
    int maxDay = 31;
    if (month == 2) {
        boolean leap = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
        maxDay = leap ? 29 : 28;
    } else if (month == 4 || month == 6 || month == 9 || month == 11) {
        maxDay = 30;
    }
    if (bucketDay > maxDay) {
        bucketDay = maxDay;
    }

    return year * 10000L + month * 100L + bucketDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    int year = (int) (timeBucket / 10000L);
    int month = (int) ((timeBucket % 10000L) / 100L);
    int day = (int) (timeBucket % 100L);

    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month in timeBucket");
    }
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid day in timeBucket");
    }

    int bucketDay = ((day - 1) / dayStep) * dayStep + 1;

    return (long) year * 10000L + (long) month * 100L + bucketDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    // Handle invalid or zero dayStep – return original bucket to avoid division by zero
    if(dayStep <= 0){
        return timeBucket;
    }
    // Extract year, month and day from the long formatted as YYYYMMDD
    long year  = timeBucket / 10000L;
    long month = (timeBucket % 10000L) / 100L;
    long day   = timeBucket % 100L;

    // Compute the new day by rounding down to the nearest block defined by dayStep
    int intDay  = (int) day;
    int newDay  = ((intDay - 1) / dayStep) * dayStep + 1;

    // Reconstruct the bucket value
    return year * 10000L + month * 100L + newDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    try {
        long year = timeBucket / 10000L;
        long month = (timeBucket % 10000L) / 100L;
        long day = timeBucket % 100L;

        // Floor the day to the nearest preceding boundary defined by dayStep
        long newDay = ((day - 1) / dayStep) * dayStep + 1;
        // Ensure the newDay does not exceed the original day
        if (newDay > day) {
            newDay = day;
        }

        return year * 10000L + month * 100L + newDay;
    } catch (Exception e) {
        // In case of any unexpected runtime error, rethrow as IllegalArgumentException
        throw new IllegalArgumentException("Failed to compress time bucket", e);
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (len < 0) {
        throw new IndexOutOfBoundsException("len is negative");
    }
    final int strLen = str.length();
    if (index < 0 || index > strLen) {
        throw new IndexOutOfBoundsException("index out of bounds");
    }
    int end = index + len;
    if (end < index) { // overflow
        throw new IndexOutOfBoundsException("int overflow");
    }
    if (end > strLen) {
        throw new IndexOutOfBoundsException("index+len exceeds string length");
    }

    int bytes = 0;
    int i = index;
    while (i < end) {
        int cp = str.codePointAt(i);
        if (cp <= 0x7F) {
            bytes += 1;
        } else if (cp <= 0x7FF) {
            bytes += 2;
        } else if (cp <= 0xFFFF) {
            bytes += 3;
        } else {
            bytes += 4;
        }
        i += Character.charCount(cp);
    }
    return bytes;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null) {
        throw new NullPointerException("String must not be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Index and length must refer to a valid substring");
    }
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x007F) {
            size += 1; // 1-byte ASCII
        } else if (ch <= 0x07FF) {
            size += 2; // 2-byte sequence
        } else if (Character.isHighSurrogate(ch)) {
            // Check for a following low surrogate
            if (i + 1 < end) {
                char low = str.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    size += 4; // 4-byte sequence for surrogate pair
                    i++; // Skip low surrogate
                } else {
                    // Invalid surrogate, use replacement character (U+FFFD, 3 bytes)
                    size += 3;
                }
            } else {
                // Trailing high surrogate without low surrogate
                size += 3;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // Lone low surrogate, use replacement character
            size += 3;
        } else {
            size += 3; // 3-byte sequence for U+0800..U+FFFF
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("String index out of bounds");
    }
    int end = index + len;
    int byteCount = 0;
    int i = index;
    while (i < end) {
        char c = str.charAt(i);
        if (Character.isHighSurrogate(c)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                byteCount += 4;
                i += 2;
                continue;
            }
        }
        if (c <= 0x7F) {
            byteCount += 1;
        } else if (c <= 0x7FF) {
            byteCount += 2;
        } else {
            byteCount += 3;
        }
        i++;
    }
    return byteCount;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null) {
        throw new NullPointerException("String cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Index or length out of range");
    }
    int bytes = 0;
    int i = index;
    int end = index + len;
    while (i < end) {
        char ch = str.charAt(i++);
        if (ch <= 0x007F) {
            bytes += 1;
        } else if (ch <= 0x07FF) {
            bytes += 2;
        } else if (Character.isHighSurrogate(ch) && i < end && Character.isLowSurrogate(str.charAt(i))) {
            // Valid surrogate pair => U+10000 to U+10FFFF: 4 bytes
            bytes += 4;
            i++; // skip low surrogate
        } else {
            // BMP character that is not ASCII => 3 bytes
            bytes += 3;
        }
    }
    return bytes;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("index or length out of bounds");
    }
    int end = index + len;
    int size = 0;
    int pos = index;
    while (pos < end) {
        char ch = str.charAt(pos);
        int codePoint;
        if (Character.isHighSurrogate(ch) && pos + 1 < end && Character.isLowSurrogate(str.charAt(pos + 1))) {
            codePoint = Character.toCodePoint(ch, str.charAt(pos + 1));
            pos += 2;
        } else {
            codePoint = ch;
            pos++;
        }
        if (codePoint <= 0x7F) {
            size += 1;
        } else if (codePoint <= 0x7FF) {
            size += 2;
        } else if (codePoint <= 0xFFFF) {
            size += 3;
        } else if (codePoint <= 0x10FFFF) {
            size += 4;
        } else {
            // replace invalid code points with the Unicode replacement character U+FFFD (3 bytes in UTF‑8)
            size += 3;
        }
    }
    return size;
}

public static <T> java.util.List<T> asList(T[] a) {
    if (a == null) {
        return java.util.Collections.<T>emptyList();
    }
    return new java.util.AbstractList<T>() {
        public T get(int index) {
            if (index < 0 || index >= a.length) {
                throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + a.length);
            }
            return a[index];
        }
        public int size() {
            return a.length;
        }
        public T set(int index, T element) {
            if (index < 0 || index >= a.length) {
                throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + a.length);
            }
            T old = a[index];
            a[index] = element;
            return old;
        }
    };
}

