public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must not be negative");
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length || byteLength > byteArrayValue.length - byteOffset) {
            throw new IndexOutOfBoundsException("byteOffset/byteLength out of bounds");
        }
    } else if (byteLength > 0) {
        // Treat as filling with null bytes
    }

    int requiredSize = length + byteLength;
    if (requiredSize > data.length) {
        int newCapacity = Math.max(data.length * 2, requiredSize);
        byte[] newData = new byte[newCapacity];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }

    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            data[length + i] = 0;
        }
    } else {
        System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
    }
    length += byteLength;
    return this;
}

