    int newSize = count + byteLength;
    if (newSize > buffer.length) {
        int newCap = Math.max(buffer.length << 1, newSize);
        buffer = java.util.Arrays.copyOf(buffer, newCap);
    }
    if (byteArrayValue == null) {
        java.util.Arrays.fill(buffer, count, count + byteLength, (byte) 0);
