private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int limit;
    int idx = 0;
    if (descriptor.charAt(0) == '(') {
        int close = descriptor.indexOf(')', 1);
        if (close == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        limit = close;
        idx = 1;
    } else {
        limit = descriptor.length();
        idx = 0;
    }
    while (idx < limit) {
        char ch = descriptor.charAt(idx);
        // skip array type brackets
        while (ch == '[') {
            idx++;
            if (idx >= limit) {
                throw new IllegalArgumentException("Invalid descriptor: array with no base type");
            }
            ch = descriptor.charAt(idx);
        }
        if (ch == 'L') {
            int semi = descriptor.indexOf(';', idx + 1);
            if (semi == -1) {
                throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
            }
            idx = semi + 1;
        } else {
            // primitives: handle single char
            idx++;
        }
        // Pop the abstract type from the stack
        outputFrameStack.pop();
    }
}

