    }
}

private void pop(final String descriptor){
    if (descriptor == null){
        throw new IllegalArgumentException("Descriptor cannot be null");
    }
    int len = descriptor.length();
    int idx = 0;
    boolean isMethod = false;
    if (len > 0 && descriptor.charAt(0) == '('){
        isMethod = true;
        idx = 1;
    }
    while (idx < len){
        char c = descriptor.charAt(idx);
        if (isMethod && c == ')'){
            break;
        }
        switch (c){
            case 'B':
            case 'C':
            case 'D':
            case 'F':
            case 'I':
            case 'Z':
            case 'S':
            case 'J':
                outputFrameStack.pop();
                idx++;
                break;
            case 'L':{
                int sem = descriptor.indexOf(';', idx);
                if (sem == -1){
                    throw new IllegalArgumentException("Invalid descriptor: missing ';'");
                }
                outputFrameStack.pop();
                idx = sem + 1;
                break;
            }
            case '[':{
                do{
                    idx++;
                } while (idx < len && descriptor.charAt(idx) == '[');
                if (idx >= len){
                    throw new IllegalArgumentException("Invalid descriptor: array type incomplete");
                }
                char comp = descriptor.charAt(idx);
                if (comp == 'L'){
                    int sem = descriptor.indexOf(';', idx);
                    if (sem == -1){
                        throw new IllegalArgumentException("Invalid descriptor: missing ';' in array");
                    }
                    idx = sem + 1;
                } else {
                    idx++; // primitive component
                }
                outputFrameStack.pop();
                break;
            }
            default:
                throw new IllegalArgumentException("Invalid descriptor character: " + c);
        }
    }
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int pops;
    if (descriptor.charAt(0) == '(') {
        int end = descriptor.indexOf(')');
        if (end < 0) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        pops = countDescriptors(descriptor.substring(1, end));
    } else {
        pops = countDescriptors(descriptor);
    }
    for (int i = 0; i < pops; i++) {
        if (outputFrameStack.isEmpty()) {
            throw new IllegalStateException("Output frame stack underflow");
        }
        outputFrameStack.pop();
    }
}

private void pop(final String descriptor) {
    // Pop abstract types from the output frame stack as described by the descriptor.
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor must not be null or empty");
    }

    // Handle method descriptors: arguments are between '(' and ')'.
    int i = 0;
    if (descriptor.charAt(0) == '(') {
        i = 1; // skip '('
        // Pop argument types
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            // Consume a type descriptor and pop from stack
            int[] skip = new int[1];
            i = popType(descriptor, i, skip);
        }
        // Skip the ')'
        if (i < descriptor.length() && descriptor.charAt(i) == ')') {
            i++;
        }
        // Pop the return type if present and not void
        if (i < descriptor.length()) {
            popReturnType(descriptor, i);
        }
    } else {
        // Simple type descriptor; pop it directly
        popReturnType(descriptor, 0);
    }
}

