private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    try {
        byte[] oldBuf = this.buffer;
        if (oldBuf == null) {
            this.buffer = new byte[size];
            return;
        }
        int newCap = oldBuf.length + size;
        if (newCap <= 0) { // overflow check
            throw new IllegalArgumentException("requested size exceeds maximum array length");
        }
        byte[] newBuf = new byte[newCap];
        System.arraycopy(oldBuf, 0, newBuf, 0, oldBuf.length);
        this.buffer = newBuf;
    } catch (OutOfMemoryError e) {
        throw new IllegalStateException("failed to enlarge byte vector due to memory exhaustion", e);
    }
}

private void enlarge(final int size){
    if (size < 0) {
        throw new IllegalArgumentException("size must be non-negative");
    }
    if (size == 0) {
        return;
    }
    // Ensure the backing array exists
    if (buffer == null) {
        buffer = new byte[size];
        return;
    }
    int requiredCapacity = this.size + size;
    if (buffer.length >= requiredCapacity) {
        return;
    }
    int newCapacity = Math.max(buffer.length * 2, requiredCapacity);
    byte[] newBuffer = new byte[newCapacity];
    System.arraycopy(buffer, 0, newBuffer, 0, this.size);
    buffer = newBuffer;
}

