private void enlarge(final int size){
    // No enlargement needed for non‑positive size
    if (size <= 0) {
        return;
    }

    // Determine new capacity: if the backing array is null start with the new size,
    // otherwise grow by the requested amount.
    int newCapacity = (bytes == null) ? size : bytes.length + size;

    // Allocate new array and copy existing data.
    byte[] newArray = new byte[newCapacity];
    if (bytes != null && bytes.length > 0) {
        System.arraycopy(bytes, 0, newArray, 0, bytes.length);
    }

    // Replace the old buffer with the enlarged one.
    bytes = newArray;
}

