public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        int length = current.tail();          // number of valid bytes in this buffer
        byte[] buffer = current.buffer();     // underlying byte array
        out.write(buffer, 0, length);         // write to the DataOutput
        totalSize += length;
        try {
            // If the LinkedBuffer provides a method to get the next buffer in the chain
            current = current.next();
        } catch (NoSuchMethodError | MissingMethodError e) {
            // If no next() method is exposed, assume this is the last buffer.
            current = null;
        }
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        int size = current.size(); // length of data in this buffer block
        if (size > 0) {
            out.write(current.getBuffer(), 0, size);
        }
        totalSize += size;
        current = current.getNext();
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) throw new IllegalArgumentException("DataOutput is null");
    if (node == null) throw new IllegalArgumentException("LinkedBuffer is null");
    byte[] buf = node.getBuffer();
    if (buf == null) return 0;
    int size = node.getSize();
    if (size < 0) size = 0;
    if (size > buf.length) size = buf.length;
    out.write(buf, 0, size);
    return size;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int total = 0;
    try {
        // Try to obtain a full byte array directly if the method exists
        java.lang.reflect.Method toBytes = node.getClass().getMethod("toByteArray");
        byte[] whole = (byte[]) toBytes.invoke(node);
        out.write(whole);
        total = whole.length;
        return total;
    } catch (Exception ignore) {
        // Method not available; fall back to iterating the buffer chain
    }
    LinkedBuffer current = node;
    try {
        java.lang.reflect.Method dataMethod = null;
        java.lang.reflect.Method sizeMethod = null;
        java.lang.reflect.Method nextMethod = null;
        try {
            dataMethod = current.getClass().getMethod("getData");
        } catch (NoSuchMethodException e) {
            dataMethod = current.getClass().getMethod("buffer");
        }
        try {
            sizeMethod = current.getClass().getMethod("getSize");
        } catch (NoSuchMethodException e) {
            sizeMethod = current.getClass().getMethod("size");
        }
        try {
            nextMethod = current.getClass().getMethod("next");
        } catch (NoSuchMethodException e) {
            try {
                nextMethod = current.getClass().getMethod("getNext");
            } catch (NoSuchMethodException e2) {
                nextMethod = null;
            }
        }
        while (current != null) {
            byte[] data = (byte[]) dataMethod.invoke(current);
            int sz = (Integer) sizeMethod.invoke(current);
            out.write(data, 0, sz);
            total += sz;
            if (nextMethod != null) {
                current = (LinkedBuffer) nextMethod.invoke(current);
            } else {
                break;
            }
        }
    } catch (Exception e) {
        throw new IOException("Failed to write LinkedBuffer contents", e);
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int total = 0;
    LinkedBuffer current = node;
    while (current != null) {
        int len = current.writerIndex - current.readerIndex;
        if (len > 0) {
            out.write(current.buf, current.readerIndex, len);
            total += len;
        }
        current = current.next;
    }
    return total;
}

