private void putAbstractTypes(final int start, final int end) {
    // Iterate over the requested slice of currentFrame and write each type
    // into stackMapTableEntries using the verification_type_info format.
    for (int i = start; i < end; i++) {
        // Retrieve the abstract type from the current frame.
        AbstractType type = currentFrame[i];
        // Determine the tag value according to the JVMS specification.
        byte tag;
        switch (type.getTag()) {
            case AbstractType.TOP:                 tag = 0; break;
            case AbstractType.INTEGER:             tag = 1; break;
            case AbstractType.FLOAT:               tag = 2; break;
            case AbstractType.LONG:                tag = 3; break;
            case AbstractType.DOUBLE:              tag = 4; break;
            case AbstractType.NULL:                tag = 5; break;
            case AbstractType.UNINITIALIZED_THIS:  tag = 6; break;
            case AbstractType.OBJECT:              tag = 7; break;
            case AbstractType.UNINITIALIZED:       tag = 8; break;
            default:
                throw new IllegalArgumentException(
                    "Unsupported AbstractType tag: " + type.getTag());
        }
        // Write the tag.
        stackMapTableEntries.writeByte(tag);

        // Types OBJECT and UNINITIALIZED require an additional 16‑bit argument.
        if (tag == 7) { // OBJECT
            int typeIndex = ((ObjectType) type).getTypeIndex();
            stackMapTableEntries.writeByte((byte) (typeIndex >>> 8));
            stackMapTableEntries.writeByte((byte) typeIndex);
        } else if (tag == 8) { // UNINITIALIZED
            int offset = ((UninitializedType) type).getOffset();
            stackMapTableEntries.writeByte((byte) (offset >>> 8));
            stackMapTableEntries.writeByte((byte) offset);
        }
    }
}

