@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Only support conversion to Character or char
    if (type != Character.class && type != char.class) {
        throw new Exception("Unsupported target type: " + type.getName());
    }
    if (value == null) {
        return null;
    }
    // If already a Character, return it
    if (value instanceof Character) {
        return value;
    }
    // If it's a String of length 1, convert to Character
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() == 1) {
            return Character.valueOf(s.charAt(0));
        }
        throw new Exception("String length must be 1 to convert to Character");
    }
    // If it's a Number, convert numeric value to char if within valid range
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal >= Character.MIN_VALUE && intVal <= Character.MAX_VALUE) {
            return Character.valueOf((char) intVal);
        }
        throw new Exception("Numeric value out of Character range");
    }
    // Unsupported value type
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Expecting conversion to java.lang.Character or primitive char
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }

    if (value == null) {
        // Allow null to be returned for reference types
        return null;
    }

    // Supported target types: Character and char
    if (type == Character.class || type == char.class) {
        if (value instanceof Character) {
            return value;
        } else if (value instanceof String) {
            String str = (String) value;
            if (str.length() == 1) {
                return str.charAt(0);
            } else {
                throw new IllegalArgumentException(
                        String.format("Cannot convert String to Character: length=%d", str.length()));
            }
        } else if (value instanceof Number) {
            // Cast numeric value to char using its integer value
            return (char) ((Number) value).intValue();
        } else if (value instanceof Boolean) {
            // Represent boolean as character '1' or '0'
            return (char) (((Boolean) value) ? 1 : 0);
        } else {
            throw new IllegalArgumentException(
                    String.format("Unsupported conversion from %s to Character", value.getClass().getName()));
        }
    }

    // If target type is not Character/char, let super handle or throw
    throw new IllegalArgumentException(
            String.format("Target type %s is not convertible by this converter", type.getName()));
}

@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    // Ensure the requested conversion type is Character
    if (!Character.class.equals(type) && !Character.TYPE.equals(type)) {
        throw new Exception("Unsupported conversion type: " + type.getName());
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return Character.valueOf(str.charAt(0));
        }
        throw new Exception("String length must be exactly 1 to convert to Character");
    }
    if (value instanceof Number) {
        return Character.valueOf((char) ((Number) value).intValue());
    }
    if (value instanceof Boolean) {
        // Arbitrary decision: true -> '1', false -> '0'
        return Character.valueOf(((Boolean) value) ? '1' : '0');
    }
    if (value instanceof char[]) {
        char[] arr = (char[]) value;
        if (arr.length == 1) {
            return Character.valueOf(arr[0]);
        }
        throw new Exception("char array length must be exactly 1 to convert to Character");
    }
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type is null");
    }
    if (value == null) {
        throw new IllegalArgumentException("Value to convert is null");
    }
    // Ensure the target type is Character or char
    if (!(Character.class.isAssignableFrom(type) || type == char.class)) {
        throw new IllegalArgumentException("Unsupported target type: " + type.getName());
    }
    // Directly return if value is already a Character
    if (value instanceof Character) {
        return value;
    }
    // Convert from String if it contains exactly one character
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() == 1) {
            return s.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert String of length " + s.length() + " to Character");
        }
    }
    // If value is a Number, attempt to cast to char
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal >= Character.MIN_VALUE && intVal <= Character.MAX_VALUE) {
            return (char) intVal;
        } else {
            throw new IllegalArgumentException("Numeric value out of char range: " + intVal);
        }
    }
    // Unsupported conversion
    throw new IllegalArgumentException("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (value == null) {
        // primitives cannot be null
        if (type.equals(char.class)) {
            throw new IllegalArgumentException("Cannot convert null to primitive char");
        }
        return null;
    }
    if (type.equals(Character.class) || type.equals(char.class)) {
        if (value instanceof Character) {
            return value;
        }
        if (value instanceof String) {
            String s = (String) value;
            if (s.length() != 1) {
                throw new IllegalArgumentException("String value must contain exactly one character for conversion to Character");
            }
            return Character.valueOf(s.charAt(0));
        }
        if (value instanceof Number) {
            int intVal = ((Number) value).intValue();
            if (intVal < Character.MIN_VALUE || intVal > Character.MAX_VALUE) {
                throw new IllegalArgumentException("Numeric value out of character range");
            }
            return Character.valueOf((char) intVal);
        }
        throw new IllegalArgumentException("Cannot convert value of type " + value.getClass().getName() + " to Character");
    }
    // if the requested type is not Character, throw an unsupported exception
    throw new UnsupportedOperationException("Conversion to type " + type.getName() + " is not supported");
}

