public static int nextPrime(int desiredCapacity){
    int candidate = Math.max(2, desiredCapacity);
    while (true) {
        if (candidate == 2) {
            return 2;
        }
        if (candidate % 2 == 0) {
            candidate++;
            continue;
        }
        boolean isPrime = true;
        for (int i = 3; (long)i * i <= candidate; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate++;
    }
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("desiredCapacity must be non-negative");
    }
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++; // start with an odd number
    }
    while (true) {
        // quick checks
        boolean isPrime = true;
        if (candidate < 2) {
            isPrime = false;
        } else if (candidate % 2 == 0) {
            isPrime = (candidate == 2);
        } else {
            int sqrt = (int) Math.sqrt(candidate);
            for (int i = 3; i <= sqrt; i += 2) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
            }
        }
        if (isPrime) {
            return candidate;
        }
        // avoid overflow
        if (candidate > Integer.MAX_VALUE - 2) {
            throw new ArithmeticException("No prime found within integer range");
        }
        candidate += 2; // skip even numbers
    }
}

public static int nextPrime(int desiredCapacity) {
    // Handle non-positive and small capacities directly
    if (desiredCapacity <= 2) {
        return 2;
    }
    int nominee = desiredCapacity;
    // Make sure nominee is odd; 2 is already handled
    if (nominee % 2 == 0) {
        nominee++;
    }
    // Search for the next prime by checking odd numbers only
    while (true) {
        if (isPrime(nominee)) {
            return nominee;
        }
        // Increment to the next odd number
        if (nominee == Integer.MAX_VALUE - 2) {
            // Avoid overflow – return max int if we exceed bounds
            return Integer.MAX_VALUE;
        }
        nominee += 2;
    }
}

