            boolean prime = true;
            for (int i = 2; (long) i * i <= n; i++) {
                if (n % i == 0) {
                    prime = false;
                    break;
                }
            }
            if (prime) {
                return n;
            }
        }
        if (n == max) {
            // exceeded allowed bound; return n anyway
            return n;
        }
        n += 2; // next odd number
    }
}

