private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> result = new HashMap<>();
    if (jsonObject == null) {
        return result;
    }
    try {
        for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
            String key = entry.getKey();
            JsonElement el = entry.getValue();
            if (el == null || el.isJsonNull()) {
                continue;
            }
            if (el.isJsonPrimitive()) {
                JsonPrimitive prim = el.getAsJsonPrimitive();
                if (prim.isBoolean()) {
                    result.put(key, prim.getAsBoolean());
                } else if (prim.isNumber()) {
                    result.put(key, prim.getAsNumber());
                } else if (prim.isString()) {
                    result.put(key, prim.getAsString());
                } else {
                    result.put(key, prim.getAsString());
                }
            } else if (el.isJsonObject()) {
                result.put(key, buildContent(el.getAsJsonObject()));
            } else if (el.isJsonArray()) {
                List<Object> list = new ArrayList<>();
                for (JsonElement inner : el.getAsJsonArray()) {
                    if (inner.isJsonPrimitive()) {
                        JsonPrimitive p = inner.getAsJsonPrimitive();
                        if (p.isBoolean()) {
                            list.add(p.getAsBoolean());
                        } else if (p.isNumber()) {
                            list.add(p.getAsNumber());
                        } else if (p.isString()) {
                            list.add(p.getAsString());
                        } else {
                            list.add(p.getAsString());
                        }
                    } else if (inner.isJsonObject()) {
                        list.add(buildContent(inner.getAsJsonObject()));
                    } else {
                        list.add(inner.toString());
                    }
                }
                result.put(key, list);
            } else {
                result.put(key, el.toString());
            }
        }
    } catch (RuntimeException e) {
        throw new IllegalStateException("Failed to build content from JSON object", e);
    }
    return result;
}

