public final byte[] toByteArray() {
    if (buffers == null || buffers.isEmpty()) {
        return new byte[0];
    }
    int total = 0;
    for (ByteBuffer buf : buffers) {
        if (buf == null) {
            continue;
        }
        total += buf.remaining();
    }
    if (total == 0) {
        return new byte[0];
    }
    byte[] result = new byte[total];
    int pos = 0;
    for (ByteBuffer buf : buffers) {
        if (buf == null) {
            continue;
        }
        ByteBuffer dup = buf.duplicate();
        int rem = dup.remaining();
        dup.get(result, pos, rem);
        pos += rem;
    }
    return result;
}

