private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate cannot be null");
    }
    // If start or stop is null, simply return a circulator pointing to stop (or null if stop is null)
    if (start == null || stop == null) {
        return new OuterFaceCirculator(stop, dir);
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node current = start;

    // Traverse the outer face starting from 'start' until we reach 'stop' or find a node satisfying 'predicate'
    while (true) {
        if (predicate.test(current)) {
            // Found a suitable node; return a circulator positioned at this node
            return new OuterFaceCirculator(current, dir);
        }
        if (current == stop) {
            // Reached the stop node; return the current circulator
            return circ;
        }

        // Move to the next node along the given direction.
        // If the underlying Node API uses a different method name for advancing, adjust accordingly.
        Node nextNode = current.getNext(dir);
        if (nextNode == null) {
            // No further node to traverse; break to avoid infinite loop
            break;
        }
        circ.move(dir);
        current = nextNode;
    }

    // If traversal ended without finding a node that satisfies the predicate or reaching 'stop',
    // return a circulator positioned at 'stop'.
    return new OuterFaceCirculator(stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("Start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("Stop node must not be null");
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // check the starting node
    if (predicate.test(circ.node())) {
        return circ;
    }

    // if start and stop are the same, we are done
    if (start.equals(stop)) {
        return circ;
    }

    while (true) {
        // advance to the next node on the outer face
        circ.next();

        Node current = circ.node();
        if (current == null) {
            // safety break in case of malformed structure
            break;
        }

        if (current.equals(stop)) {
            // reached the stop node without satisfying predicate
            break;
        }

        if (predicate.test(current)) {
            return circ;
        }
    }

    // return a circulator positioned at the stop node
    return new OuterFaceCirculator(stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null) {
        throw new IllegalArgumentException("predicate cannot be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node cannot be null");
    }
    // Construct the circulator starting from the given node and direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node current = start;
    // Iterate until we find a node that satisfies the predicate, hit the stop node,
    // or we loop back to the starting node (indicating no match on this face).
    while (current != null) {
        if (predicate.test(current)) {
            return circ;
        }
        if (stop != null && current.equals(stop)) {
            return circ;
        }
        current = circ.next();
        if (current != null && current.equals(start)) {
            break;
        }
    }
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null || start == null || stop == null) {
        return new OuterFaceCirculator(stop);
    }
    Node current = start;
    while (current != null && current != stop && !predicate.test(current)) {
        // Move to the next node on the boundary in the given direction.
        // Assumes Node provides a method for accessing the next boundary node.
        current = current.getNextInDirection(dir);
    }
    return new OuterFaceCirculator(current != null ? current : stop);
}

