protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null){
        throw new IllegalArgumentException("tour must not be null");
    }
    if (graph == null){
        throw new IllegalArgumentException("graph must not be null");
    }
    if (tour.isEmpty()){
        return null;
    }
    List<E> edgePath = new ArrayList<>();
    List<V> vertexPath = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);

    // start with an arbitrary edge
    E firstEdge = remaining.iterator().next();
    remaining.remove(firstEdge);
    V startVertex = graph.getEdgeSource(firstEdge);
    V currentVertex = graph.getEdgeTarget(firstEdge);

    vertexPath.add(startVertex);
    edgePath.add(firstEdge);
    vertexPath.add(currentVertex);
    currentVertex = currentVertex;

    // iterate until all edges are consumed
    while (!remaining.isEmpty()){
        boolean found = false;
        Iterator<E> it = remaining.iterator();
        while (it.hasNext()){
            E e = it.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(currentVertex)){
                edgePath.add(e);
                vertexPath.add(tgt);
                currentVertex = tgt;
                it.remove();
                found = true;
                break;
            } else if (tgt.equals(currentVertex)){
                edgePath.add(e);
                vertexPath.add(src);
                currentVertex = src;
                it.remove();
                found = true;
                break;
            }
        }
        if (!found){
            throw new IllegalArgumentException("Edges do not form a continuous tour");
        }
    }

    double weight = 0.0;
    for (E e : edgePath){
        weight += graph.getEdgeWeight(e);
    }

    return new GraphPathImpl<>(graph, vertexPath.get(0), currentVertex, weight, vertexPath, edgePath);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphWalk<>(graph, null, null, java.util.Collections.emptyList(), 0.0);
    }
    java.util.Set<E> remaining = new java.util.HashSet<>(tour);
    java.util.Iterator<E> it = remaining.iterator();
    E firstEdge = it.next();
    remaining.remove(firstEdge);
    java.util.List<E> orderedEdges = new java.util.ArrayList<>();
    orderedEdges.add(firstEdge);
    V start = graph.getEdgeSource(firstEdge);
    V current = graph.getEdgeTarget(firstEdge);
    while (!remaining.isEmpty()) {
        boolean found = false;
        java.util.Iterator<E> ri = remaining.iterator();
        while (ri.hasNext()) {
            E e = ri.next();
            V s = graph.getEdgeSource(e);
            V t = graph.getEdgeTarget(e);
            if (java.util.Objects.equals(s, current)) {
                orderedEdges.add(e);
                current = t;
                found = true;
                ri.remove();
                break;
            } else if (java.util.Objects.equals(t, current)) {
                orderedEdges.add(e);
                current = s;
                found = true;
                ri.remove();
                break;
            }
        }
        if (!found) {
            throw new IllegalArgumentException("Edges do not form a continuous tour");
        }
    }
    return new GraphWalk<>(graph, start, current, orderedEdges, 0.0);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour == null || graph == null) {
        return null;
    }
    try {
        if (tour.isEmpty()) {
            return null;
        }
        // Build adjacency map from vertex to list of incident edges
        Map<V, List<E>> adjacency = new HashMap<>();
        for (E e : tour) {
            V source = graph.getEdgeSource(e);
            V target = graph.getEdgeTarget(e);
            adjacency.computeIfAbsent(source, k -> new ArrayList<>()).add(e);
            adjacency.computeIfAbsent(target, k -> new ArrayList<>()).add(e);
        }
        // Pick arbitrary start vertex
        V startVertex = adjacency.keySet().iterator().next();
        // Prepare to construct ordered edge list
        List<E> orderedEdges = new ArrayList<>();
        Set<E> remainingEdges = new HashSet<>(tour);
        // Start from an arbitrary edge
        E current = remainingEdges.iterator().next();
        orderedEdges.add(current);
        remainingEdges.remove(current);
        V currentVertex = graph.getEdgeTarget(current);
        // Traverse remaining edges
        while (!remainingEdges.isEmpty()) {
            List<E> candidates = adjacency.get(currentVertex);
            if (candidates == null) break;
            E nextEdge = null;
            for (E e : candidates) {
                if (remainingEdges.contains(e)) {
                    nextEdge = e;
                    break;
                }
            }
            if (nextEdge == null) {
                // No connecting edge found; break out
                break;
            }
            orderedEdges.add(nextEdge);
            remainingEdges.remove(nextEdge);
            V s = graph.getEdgeSource(nextEdge);
            V t = graph.getEdgeTarget(nextEdge);
            currentVertex = s.equals(currentVertex) ? t : s;
        }
        // Determine path end vertex
        V endVertex;
        if (orderedEdges.isEmpty()) {
            endVertex = startVertex;
        } else {
            E last = orderedEdges.get(orderedEdges.size() - 1);
            V s = graph.getEdgeSource(last);
            V t = graph.getEdgeTarget(last);
            endVertex = (orderedEdges.size() == 1 && s.equals(startVertex)) ? t : (s.equals(t) ? s : (s.equals(startVertex) ? t : s));
        }
        // Construct GraphPath (weight is set to 0)
        return new GraphPathImpl<V, E>(graph, startVertex, endVertex, orderedEdges, 0);
    } catch (Exception e) {
        // In case of any error, return null
        return null;
    }
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (graph == null || tour == null) {
        throw new IllegalArgumentException("Graph and tour must not be null");
    }
    if (tour.isEmpty()) {
        return new DefaultGraphPath<>(graph, new ArrayList<V>(), new ArrayList<E>());
    }
    // Build adjacency map
    java.util.Map<V, java.util.List<E>> adj = new java.util.HashMap<>();
    for (E edge : tour) {
        if (!graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Edge not in graph: " + edge);
        }
        V src = graph.getEdgeSource(edge);
        V tgt = graph.getEdgeTarget(edge);
        adj.computeIfAbsent(src, k -> new java.util.ArrayList<>()).add(edge);
        adj.computeIfAbsent(tgt, k -> new java.util.ArrayList<>()).add(edge);
    }
    // Find start vertex (vertex with degree 1 or arbitrary if cycle)
    V start = null;
    for (java.util.Map.Entry<V, java.util.List<E>> entry : adj.entrySet()) {
        if (entry.getValue().size() == 1) {
            start = entry.getKey();
            break;
        }
    }
    if (start == null) {
        // cycle: pick any vertex
        start = adj.keySet().iterator().next();
    }
    // Construct path
    java.util.List<E> edgePath = new java.util.ArrayList<>();
    java.util.List<V> vertexPath = new java.util.ArrayList<>();
    java.util.Set<E> used = new java.util.HashSet<>();
    V cur = start;
    vertexPath.add(cur);
    while (true) {
        java.util.List<E> candidates = adj.get(cur);
        if (candidates == null) {
            break;
        }
        E nextEdge = null;
        for (E e : candidates) {
            if (!used.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            break;
        }
        used.add(nextEdge);
        edgePath.add(nextEdge);
        V next = graph.getEdgeSource(nextEdge).equals(cur) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        vertexPath.add(next);
        cur = next;
    }
    if (edgePath.size() != tour.size()) {
        throw new IllegalStateException("Tour does not connect all edges");
    }
    return new DefaultGraphPath<>(graph, vertexPath, edgePath);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new DefaultGraphPath<>(graph, Collections.emptyList(), Collections.emptyList());
    }
    // Build adjacency list for vertices
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(e);
    }
    // Start from an arbitrary vertex (source of first edge)
    V startVertex = graph.getEdgeSource(tour.iterator().next());
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();
    vertexList.add(startVertex);
    V current = startVertex;
    while (visitedEdges.size() < tour.size()) {
        List<E> candidates = adjacency.get(current);
        if (candidates == null) {
            throw new IllegalArgumentException("Cannot build a continuous tour from the given edge set");
        }
        boolean progressed = false;
        for (E e : candidates) {
            if (visitedEdges.contains(e)) {
                continue;
            }
            visitedEdges.add(e);
            edgeList.add(e);
            V next = graph.getEdgeSource(e).equals(current) ? graph.getEdgeTarget(e) : graph.getEdgeSource(e);
            vertexList.add(next);
            current = next;
            progressed = true;
            break;
        }
        if (!progressed) {
            throw new IllegalArgumentException("Edge set does not form a continuous path");
        }
    }
    return new DefaultGraphPath<>(graph, vertexList, edgeList);
}

