        while (newCap - count < 4) {
            newCap <<= 1;
        }
        buffer = java.util.Arrays.copyOf(buffer, newCap);
    }
    buffer[count++] = (byte) (intValue >> 24);
    buffer[count++] = (byte) (intValue >> 16);
    buffer[count++] = (byte) (intValue >> 8);
    buffer[count++] = (byte) intValue;
    return this;
}

public ByteVector putInt(final int intValue){
    int newSize = size + 4;
    if (buf == null) {
        buf = new byte[Math.max(16, newSize)];
    } else if (newSize > buf.length) {
        int newCapacity = Math.max(newSize, buf.length * 2);
        byte[] larger = new byte[newCapacity];
        System.arraycopy(buf, 0, larger, 0, size);
        buf = larger;
    }
    buf[size]     = (byte)(intValue >> 24);
    buf[size + 1] = (byte)(intValue >> 16);
    buf[size + 2] = (byte)(intValue >> 8);
    buf[size + 3] = (byte)intValue;
    size = newSize;
    return this;
}

