public void abbreviate(final int nameStart,final StringBuffer buf){
    if (buf == null) {
        throw new NullPointerException("Buffer cannot be null");
    }
    if (nameStart < 0 || nameStart > buf.length()) {
        throw new IllegalArgumentException("nameStart out of bounds");
    }
    String remaining = buf.substring(nameStart);
    if (remaining.isEmpty()) {
        return;
    }
    StringBuilder abbr = new StringBuilder();
    String[] parts = remaining.split("[^A-Za-z0-9]+");
    for (String part : parts) {
        if (!part.isEmpty()) {
            abbr.append(part.charAt(0));
        }
    }
    buf.append(abbr);
}

public void abbreviate(final int nameStart,final StringBuffer buf){
    if (buf == null) {
        return;
    }
    int len = buf.length();
    if (nameStart < 0 || nameStart > len) {
        return;
    }

    // Build abbreviation from the start index to the end of the buffer.
    StringBuilder abbrev = new StringBuilder();
    boolean startOfWord = true;
    for (int i = nameStart; i < len; i++) {
        char ch = buf.charAt(i);
        if (startOfWord && Character.isJavaIdentifierPart(ch)) {
            abbrev.append(ch);
            startOfWord = false;
        }
        if (ch == '.' || ch == '_' || ch == '-' || ch == ' ') {
            startOfWord = true;
        }
    }

    // Replace the original segment with the abbreviation.
    buf.delete(nameStart, len);
    buf.append(abbrev);
}

