        return;
    }
    if (nameStart < 0 || nameStart > buf.length()) {
        return;
    }
    try {
        String name = buf.substring(nameStart);
        if (name.isEmpty()) {
            return;
        }
        String[] parts = name.split("\\.");
        if (parts.length <= 1) {
            return; // nothing to abbreviate
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < parts.length - 1; i++) {
            if (!parts[i].isEmpty()) {
                sb.append(parts[i].charAt(0)).append(".");
            }
        }
        sb.append(parts[parts.length - 1]);
        buf.replace(nameStart, buf.length(), sb.toString());
    } catch (IndexOutOfBoundsException | NullPointerException e) {
        // ignore or handle appropriately
    }
}

public void abbreviate(final int nameStart,final StringBuffer buf){
    // The abbreviation routine operates on the instance's name field.
    // It shortens package prefixes to first character only, preserving
    // the last component entirely.
    String n = this.name; // assume field `name` holds the full qualified name
    if (n == null) {
        return;
    }
    int len = n.length();
    if (nameStart >= len) {
        return;
    }
    for (int i = nameStart; i < len; i++) {
        char c = n.charAt(i);
        if (c == '.') {
            buf.append('.');
            i++;
            if (i >= len) {
                break;
            }
            buf.append(n.charAt(i)); // only first char of component
            // skip remainder of component until next dot
            while (i + 1 < len && n.charAt(i + 1) != '.') {
                i++;
            }
        } else {
            // last component – append full remainder
            buf.append(n, i, len);
            break;
        }
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
