private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("graph and vertices must not be null");
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertex set must not be null");
    }
    int size = vertices.size();
    if (size <= 1) { // empty or single vertex is trivially a clique
        return true;
    }
    // Convert to array for indexed access
    Object[] verts = vertices.toArray();
    for (int i = 0; i < size; i++) {
        @SuppressWarnings("unchecked")
        V v1 = (V) verts[i];
        if (v1 == null) {
            throw new IllegalArgumentException("Vertex set contains null");
        }
        for (int j = i + 1; j < size; j++) {
            @SuppressWarnings("unchecked")
            V v2 = (V) verts[j];
            if (v2 == null) {
                throw new IllegalArgumentException("Vertex set contains null");
            }
            // For undirected graph: check edge either direction
            if (!(graph.containsEdge(v1, v2) || graph.containsEdge(v2, v1))) {
                return false;
            }
        }
    }
    return true;
}

