    List<V> list = new ArrayList<>(vertices);
    for (int i = 0; i < size - 1; i++) {
        V vi = list.get(i);
        for (int j = i + 1; j < size; j++) {
            V vj = list.get(j);
            // For undirected graphs, containsEdge(v1, v2) suffices.
            // For directed graphs, ensure at least one direction exists.
            if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
