                if (i < len && descriptor.charAt(i) == 'L') {
                    i++;
                    while (i < len && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    i++; // skip ';'
                } else {
                    i++; // primitive component after '['
                }
            } else if (c == 'L') {
                i++;
                while (i < len && descriptor.charAt(i) != ';') {
                    i++;
                }
                i++; // skip ';'
            } else {
                i++; // primitive
            }
            outputStack.pop();
        }
    } catch (Exception e) {
        // malformed descriptor; ignore silently
    }
}

private void pop(final String descriptor) {
    int slots = 0;
    int i = 0;
    final int length = descriptor.length();
    if (length == 0) {
        throw new IllegalArgumentException("Descriptor cannot be empty");
    }
    // Handle method descriptors
    if (descriptor.charAt(i) == '(') {
        i++; // skip '('
        while (i < length && descriptor.charAt(i) != ')') {
            // Count array dimensions
            while (i < length && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= length) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            char type = descriptor.charAt(i++);
            if (type == 'L') {
                // Reference type: consume up to ';'
                while (i < length && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i >= length) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                i++; // skip ';'
                slots += 1; // reference types occupy one slot
            } else {
                // Primitive types
                if (type == 'J' || type == 'D') {
                    slots += 2; // long and double occupy two slots
                } else {
                    slots += 1; // all other primitives occupy one slot
                }
            }
        }
        // Skip the ')' that ends the parameter list
        if (i >= length || descriptor.charAt(i) != ')') {
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
        // No action needed for return type
    } else {
        // Single type descriptor
        while (i < length) {
            while (i < length && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= length) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            char type = descriptor.charAt(i++);
            if (type == 'L') {
                while (i < length && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i >= length) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                i++; // skip ';'
                slots += 1;
            } else {
                if (type == 'J' || type == 'D') {
                    slots += 2;
                } else {
                    slots += 1;
                }
            }
        }
    }

    // Pop the calculated number of slots from the output frame stack.
    for (int j = 0; j < slots; j++) {
        if (outputFrame.isEmpty()) {
            throw new IllegalStateException("Attempted to pop from an empty output frame stack");
        }
        outputFrame.pop();
    }
}

private void pop(final String descriptor){
    if (descriptor == null){
        return;
    }
    int slots = 0;
    if (descriptor.startsWith("(")){
        int end = descriptor.indexOf(')');
        if (end < 0){
            throw new IllegalArgumentException("invalid descriptor: missing ')'");
        }
        String args = descriptor.substring(1, end);
        int i = 0;
        while (i < args.length()){
            char c = args.charAt(i);
            if (c == 'L'){
                int semi = args.indexOf(';', i+1);
                if (semi < 0){
                    throw new IllegalArgumentException("invalid descriptor: missing ';'");
                }
                slots++;
                i = semi + 1;
            }else if (c == '['){
                i++;
                while (i < args.length() && args.charAt(i) == '['){
                    i++;
                }
                if (i < args.length() && args.charAt(i) == 'L'){
                    int semi = args.indexOf(';', i+1);
                    if (semi < 0){
                        throw new IllegalArgumentException("invalid descriptor: missing ';'");
                    }
                    i = semi + 1;
                }else if (i < args.length()){
                    i++;
                }
                slots++;
            }else{
                if (c == 'J' || c == 'D'){
                    slots += 2;
                }else if ("BCSFI".indexOf(c) >= 0 || c == 'Z'){
                    slots++;
                }else if (c == 'V'){
                    // no stack slot
                }else{
                    throw new IllegalArgumentException("invalid descriptor: unknown type " + c);
                }
                i++;
            }
        }
    }else{
        int i = 0;
        while (i < descriptor.length()){
            char c = descriptor.charAt(i);
            if (c == 'L'){
                int semi = descriptor.indexOf(';', i+1);
                if (semi < 0){
                    throw new IllegalArgumentException("invalid descriptor: missing ';'");
                }
                slots++;
                i = semi + 1;
            }else if (c == '['){
                i++;
                while (i < descriptor.length() && descriptor.charAt(i) == '['){
                    i++;
                }
                if (i < descriptor.length() && descriptor.charAt(i) == 'L'){
                    int semi = descriptor.indexOf(';', i+1);
                    if (semi < 0){
                        throw new IllegalArgumentException("invalid descriptor: missing ';'");
                    }
                    i = semi + 1;
                }else if (i < descriptor.length()){
                    i++;
                }
                slots++;
            }else{
                if (c == 'J' || c == 'D'){
                    slots += 2;
                }else if ("BCSFI".indexOf(c) >= 0 || c == 'Z'){
                    slots++;
                }else if (c == 'V'){
                    // no stack slot
                }else{
                    throw new IllegalArgumentException("invalid descriptor: unknown type " + c);
                }
                i++;
            }
        }
    }
    for (int j = 0; j < slots; j++){
        outputFrameStack.pop();
    }
}

