private List<Integer> computeUpperBounds(List<K> keys){ 
    List<Integer> bounds = new ArrayList<>(); 
    if (keys == null){ 
        return bounds; 
    } 
    TreeSet<Integer> set = new TreeSet<>(); 
    for (K k : keys){ 
        if (k == null){ 
            continue; 
        } 
        try{ 
            set.add((Integer)k); 
        }catch(ClassCastException e){ 
            // key not an Integer, skip or handle accordingly 
            continue; 
        } 
    } 
    for (K k : keys){ 
        if (k == null){ 
            bounds.add(null); 
            continue; 
        } 
        try{ 
            Integer val = (Integer)k; 
            Integer upper = set.higher(val); 
            bounds.add(upper != null ? upper : Integer.MAX_VALUE); 
        }catch(ClassCastException e){ 
            bounds.add(null); 
        } 
    } 
    return bounds; 
}

private List<Integer> computeUpperBounds(List<K> keys){
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return result;
    }
    // Extract Integer values from the generic keys
    java.util.List<Integer> intKeys = new java.util.ArrayList<>(keys.size());
    for (K k : keys){
        if (k instanceof Integer){
            intKeys.add((Integer) k);
        } else {
            throw new IllegalArgumentException("Key type must be Integer");
        }
    }
    // Sorted copy for searching
    java.util.List<Integer> sorted = new java.util.ArrayList<>(intKeys);
    java.util.Collections.sort(sorted);
    // For each key find the minimal greater key (upper bound)
    for (Integer key : intKeys){
        int idx = java.util.Collections.binarySearch(sorted, key);
        if (idx < 0){
            idx = -idx - 1;
        }
        if (idx < sorted.size() - 1){
            result.add(sorted.get(idx + 1));
        } else {
            result.add(key); // no greater key, use key itself
        }
    }
    return result;
}

