public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        throw new IllegalArgumentException("path must not be null");
    }
    if (relativePath == null) {
        throw new IllegalArgumentException("relativePath must not be null");
    }

    // Determine base directory from the given path.
    String base = path;
    int lastSlash = base.lastIndexOf('/');
    if (lastSlash >= 0) {
        // Keep the trailing slash for proper concatenation
        base = base.substring(0, lastSlash + 1);
    } else {
        base = "";
    }

    // Combine base with the relative path
    String combined = base + relativePath;

    // Normalize the combined path
    String[] parts = combined.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();
    String prefix = combined.startsWith("/") ? "/" : "";

    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
            // If stack is empty and part is "..", we ignore for absolute paths.
            continue;
        }
        stack.push(part);
    }

    // Build the final path string
    java.lang.StringBuilder sb = new java.lang.StringBuilder();
    sb.append(prefix);
    java.util.Iterator<String> it = stack.descendingIterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) {
            sb.append("/");
        }
    }
    return sb.toString();
}

public static String applyRelativePath(String path,String relativePath){
    if(path==null||relativePath==null){
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    boolean absolute=path.startsWith("/");
    java.util.Deque<String> stack=new java.util.ArrayDeque<>();
    for(String seg:path.split("/")){
        if(seg.isEmpty()||seg.equals(".")) continue;
        if(seg.equals("..")){
            if(!stack.isEmpty()){
                stack.removeLast();
            }else if(!absolute){
                stack.addLast("..");
            }
        }else{
            stack.addLast(seg);
        }
    }
    for(String seg:relativePath.split("/")){
        if(seg.isEmpty()||seg.equals(".")) continue;
        if(seg.equals("..")){
            if(!stack.isEmpty()){
                stack.removeLast();
            }else if(!absolute){
                stack.addLast("..");
            }
        }else{
            stack.addLast(seg);
        }
    }
    StringBuilder sb=new StringBuilder();
    if(absolute) sb.append("/");
    for(java.util.Iterator<String> it=stack.iterator();it.hasNext();){
        sb.append(it.next());
        if(it.hasNext()){
            sb.append("/");
        }
    }
    String result=sb.toString();
    if(result.isEmpty()){
        return absolute?"/":".";
    }
    return result;
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null) path = "";
    if (relativePath == null) relativePath = "";
    // Normalise separators to '/'
    path = path.replace('\\', '/');
    relativePath = relativePath.replace('\\', '/');
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    java.util.StringTokenizer tokPath = new java.util.StringTokenizer(path, "/");
    while (tokPath.hasMoreTokens()) {
        String part = tokPath.nextToken();
        if (part.equals(".") || part.isEmpty()) continue;
        stack.add(part);
    }
    java.util.StringTokenizer tokRel = new java.util.StringTokenizer(relativePath, "/");
    while (tokRel.hasMoreTokens()) {
        String part = tokRel.nextToken();
        if (part.equals(".") || part.isEmpty()) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty()) stack.removeLast();
        } else {
            stack.add(part);
        }
    }
    java.lang.StringBuilder sb = new java.lang.StringBuilder();
    boolean isAbsolute = path.startsWith("/");
    if (isAbsolute) sb.append("/");
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) sb.append("/");
    }
    if (sb.length() == 0) return ".";
    return sb.toString();
}

public static String applyRelativePath(String path, String relativePath){
    // Handle null or empty inputs gracefully
    if (path == null || path.isEmpty()) {
        return relativePath != null ? relativePath : "";
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    try {
        boolean sourceAbsolute = path.startsWith("/");
        int lastSlash = path.lastIndexOf('/');
        String baseDir;
        if (lastSlash >= 0) {
            baseDir = path.substring(0, lastSlash + 1); // keep trailing slash
        } else {
            baseDir = "";
        }
        String combined = baseDir + relativePath;
        boolean combinedAbsolute = combined.startsWith("/");
        String[] parts = combined.split("/");
        java.util.List<String> stack = new java.util.ArrayList<>();
        for (String part : parts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!stack.isEmpty() && !stack.get(stack.size() - 1).equals("..")) {
                    stack.remove(stack.size() - 1);
                } else {
                    // Preserve ".." only if resulting path is relative
                    if (!combinedAbsolute) {
                        stack.add("..");
                    }
                }
            } else {
                stack.add(part);
            }
        }
        StringBuilder sb = new StringBuilder();
        if (combinedAbsolute) {
            sb.append("/");
        }
        for (int i = 0; i < stack.size(); i++) {
            if (i > 0) sb.append("/");
            sb.append(stack.get(i));
        }
        if (stack.isEmpty() && combinedAbsolute) {
            return "/";
        }
        return sb.toString();
    } catch (Exception e) {
        // In case of unexpected errors, fallback to simple concatenation
        String fallback = relativePath.replace("\\", "/");
        if (!fallback.startsWith("/") && !path.endsWith("/")) {
            fallback = "/" + fallback;
        }
        return path + fallback;
    }
}

public static String applyRelativePath(String path, String relativePath) {
    try {
        if (path == null || path.isEmpty()) {
            return relativePath;
        }
        if (relativePath == null || relativePath.isEmpty()) {
            return path;
        }
        // Normalize separators to '/'
        String normPath = path.replace("\\", "/");
        String normRel = relativePath.replace("\\", "/");
        java.nio.file.Path rel = java.nio.file.Paths.get(normRel);
        if (rel.isAbsolute()) {
            return normRel;
        }
        java.nio.file.Path base = java.nio.file.Paths.get(normPath);
        java.nio.file.Path baseDir = base.getParent() != null ? base.getParent() : base;
        java.nio.file.Path resolved = baseDir.resolve(rel).normalize();
        String result = resolved.toString();
        // Ensure '/' as separator
        String sysSep = java.nio.file.FileSystems.getDefault().getSeparator();
        if (!"/".equals(sysSep)) {
            result = result.replace(sysSep, "/");
        }
        return result;
    } catch (Exception e) {
        // Fallback simple join if any exception occurs
        if (path.endsWith("/")) {
            return path + relativePath;
        }
        return path + "/" + relativePath;
    }
}

