public static int indexOfExtension(String filename){
    if (filename == null) { return -1; }
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) { return -1; }
    int lastSep = indexOfLastSeparator(filename);
    if (lastSep >= lastDot) { return -1; }
    return lastDot;
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }
    // Determine the last path separator (Unix '/' or Windows '\\')
    int lastForwardSlash = filename.lastIndexOf('/');
    int lastBackSlash = filename.lastIndexOf('\\');
    int lastSeparator = Math.max(lastForwardSlash, lastBackSlash);
    // If there is a separator after the last dot, the dot is part of the path, not an extension
    if (lastSeparator > dotIndex) {
        return -1;
    }
    return dotIndex;
}

