public boolean isExpired(long timestamp, long expiredThreshold) {
    if (expiredThreshold < 0) {
        // Negative threshold is treated as already expired
        return true;
    }
    long currentTime = System.currentTimeMillis();
    // Prevent overflow when subtracting timestamps
    long elapsed;
    try {
        elapsed = Math.subtractExact(currentTime, timestamp);
    } catch (ArithmeticException e) {
        // If overflow occurs, consider it expired
        return true;
    }
    return elapsed > expiredThreshold;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        if (expiredThreshold <= 0) {
            return true; // consider expired if threshold is non-positive
        }
        long current = System.currentTimeMillis();
        return current - timestamp > expiredThreshold;
    } catch (Throwable t) {
        // In case of any unexpected error, consider the metric expired
        return true;
    }
}

