private void checkIfPackedField() throws IOException {
    // Packed repeated fields are encoded with the LENGTH_DELIMITED wire type (value 2).
    // Assume the current tag is stored in a field called `tag` and that an internal
    // flag `isPackedField` (or similar) is available to indicate whether we are
    // currently reading a packed field.
    int wireType = this.tag & 0x7;      // lower three bits hold the wire type
    if (wireType == 2) {                // LENGTH_DELIMITED
        this.isPackedField = true;
    } else {
        this.isPackedField = false;
    }
}

private void checkIfPackedField() throws IOException {
    // Determine the wire type of the current field. In protobuf, a
    // packed repeated field is encoded as a length‑delimited field
    // (wire type 2).  The parser keeps the current tag in the
    // variable `lastTag` and the field number in `fieldNumber`.
    int wireType = lastTag & 0x7;
    if (wireType == 2) {
        // Only a repeated field can be packed.  The helper method
        // `isPackedRepeated(fieldNumber)` returns true if the schema
        // declares this field as a packed repeated field.
        if (isPackedRepeated(fieldNumber)) {
            // Mark that packed data is being read.  The field
            // `packed` is used by the rest of the parser to decide
            // whether to treat the incoming bytes as a pack of
            // primitive values.
            packed = true;
        } else {
            packed = false;
        }
    } else {
        // Any wire type other than length‑delimited cannot be packed.
        packed = false;
    }
}

private void checkIfPackedField() throws IOException {
    // The current tag is stored in `lastTag`. Packed fields use a length‑delimited wire type
    // but represent repeated primitive values.
    if ((lastTag & 0x07) == WIRETYPE_LENGTH_DELIMITED && isPackedPrimitiveTag(lastTag)) {
        // We are entering a packed field; set state accordingly.
        isReadingPacked = true;
        int packedSize = readRawVarint32();
        packedBytesLimit = pos + packedSize;
        limit = packedBytesLimit;
    } else {
        isReadingPacked = false;
    }
}

private void checkIfPackedField() throws IOException {
    // Attempt to peek at the next tag to determine if we are at a packed field
    int tag = getNextTag(); // may throw IOException
    // Wire type is the lower 3 bits of the tag
    int wireType = tag & 0x07;
    // In protobuf, length-delimited wire type is 2
    if (wireType == 2) {
        // Field number is the remaining bits
        int fieldNumber = tag >>> 3;
        // Verify that this field is a packed repeated field by consulting the descriptor
        if (isPackedRepeatedField(fieldNumber)) {
            // Update internal state to indicate packed mode
            this.inPackedMode = true;
            // Reset packed count if needed
            this.packedCount = 0;
        }
    }
}

