public int readTag() throws IOException {
    try {
        int firstByte = readRawByte();
        if ((firstByte & 0x80) == 0) {
            return firstByte;
        }
        int tag = firstByte & 0x7F;
        int shift = 7;
        while (shift < 32) {
            int b = readRawByte();
            tag |= (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                break;
            }
            shift += 7;
        }
        return tag;
    } catch (java.io.EOFException e) {
        return 0;
    }
}

public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    int b;
    while (true) {
        b = in.read();
        if (b == -1) {
            return 0; // EOF reached, no tag
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result; // successfully read varint tag
        }
        shift += 7;
        if (shift > 35) { // more than 5 bytes, malformed varint
            throw new IOException("Malformed varint");
        }
    }
}

