    return String.format("bytes %d-%d/*", start, end);
}

private String buildContentRange() {
    // Build the 'Content-Range' HTTP header value in the form:
    //   bytes {start}-{end}/{total}
    // Where:
    //   - start   : the starting byte position of the content chunk,
    //   - end     : the ending byte position of the content chunk,
    //   - total   : the total size of the complete resource (if known).
    // Fallback logic is provided for unknown total sizes.
    long start = contentStartPosition;                  // starting offset of this chunk
    long end   = start + contentSize - 1;               // inclusive end offset
    long total = memMapSize;                            // total resource size

    // If the total size is unknown or invalid, we return the header without
    // the total field, signalling that the size is unknown (using '*')
    if (total <= 0) {
        return String.format("bytes %d-%d/*", start, end);
    }
    return String.format("bytes %d-%d/%d", start, end, total);
}

private String buildContentRange(){
    try{
        java.lang.reflect.Field[] fields = this.getClass().getDeclaredFields();
        java.lang.reflect.Field startField=null, endField=null, totalField=null;
        for(java.lang.reflect.Field f: fields){
            String n = f.getName();
            if(startField==null && (n.equals("contentStartPosition")||n.equals("offset")||n.equals("start")||n.equals("startPosition"))){
                startField = f;
            }else if(endField==null && (n.equals("contentEndPosition")||n.equals("end")||n.equals("endPosition"))){
                endField = f;
            }else if(totalField==null && (n.equals("contentLength")||n.equals("contentSize")||n.equals("totalSize")||n.equals("totalLength")||n.equals("size")||n.equals("length"))){
                totalField = f;
            }
        }
        if(startField==null || endField==null || totalField==null){
            return "bytes */*";
        }
        startField.setAccessible(true);
        endField.setAccessible(true);
        totalField.setAccessible(true);
        Object startObj = startField.get(this);
        Object endObj   = endField.get(this);
        Object totalObj = totalField.get(this);
        if(startObj==null || endObj==null || totalObj==null){
            return "bytes */*";
        }
        long start = ((Number)startObj).longValue();
        long end   = ((Number)endObj).longValue();
        long total = ((Number)totalObj).longValue();
        return "bytes " + start + "-" + end + "/" + total;
    }catch(Exception e){
        return "bytes */*";
    }
}

private String buildContentRange(){
    long start = 0L;
    long length = 0L;
    long total = 0L;
    try{
        java.lang.reflect.Field fStart = this.getClass().getDeclaredField("offset");
        fStart.setAccessible(true);
        Object val = fStart.get(this);
        if(val instanceof Number){
            start = ((Number)val).longValue();
        }
    }catch(Exception e){}
    try{
        java.lang.reflect.Field fLen = this.getClass().getDeclaredField("contentLength");
        fLen.setAccessible(true);
        Object val = fLen.get(this);
        if(val instanceof Number){
            length = ((Number)val).longValue();
        }
    }catch(Exception e){}
    try{
        java.lang.reflect.Field fTotal = this.getClass().getDeclaredField("totalSize");
        fTotal.setAccessible(true);
        Object val = fTotal.get(this);
        if(val instanceof Number){
            total = ((Number)val).longValue();
        }
    }catch(Exception e){}
    long end = start + length - 1;
    return "bytes " + start + "-" + end + "/" + total;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        return snapshots;
    }
    BufferedReader reader = null;
    try {
        reader = new BufferedReader(new FileReader(file));
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot ts = null;
            try {
                ts = ThreadSnapshot.parse(line); // Assume ThreadSnapshot has a static parse method
            } catch (Exception e) {
                // Skip malformed lines
                continue;
            }
            if (ts == null) {
                continue;
            }
            if (timeRanges == null || timeRanges.isEmpty()) {
                snapshots.add(ts);
            } else {
                long timestamp = ts.getTimestamp(); // Assume ThreadSnapshot has getTimestamp()
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (timestamp >= range.getStart() && timestamp <= range.getEnd()) {
                        snapshots.add(ts);
                        break;
                    }
                }
            }
        }
    } finally {
        if (reader != null) {
            try {
                reader.close();
            } catch (IOException ignored) {
            }
        }
    }
    return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file cannot be null");
    }
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    // If there is no specific time range specified, return all snapshots in file
    boolean filterByTime = timeRanges != null && !timeRanges.isEmpty();
    try (ObjectInputStream ois = new ObjectInputStream(new java.io.BufferedInputStream(new java.io.FileInputStream(file)))) {
        while (true) {
            try {
                Object obj = ois.readObject();
                if (!(obj instanceof ThreadSnapshot)) {
                    continue; // skip unexpected objects
                }
                ThreadSnapshot ts = (ThreadSnapshot) obj;
                if (!filterByTime) {
                    snapshots.add(ts);
                    continue;
                }
                long tsTime = ts.getTimestamp(); // Assume ThreadSnapshot has getTimestamp()
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    long start = range.getStartTime(); // Assume ProfileAnalyzeTimeRange has getStartTime()
                    long end = range.getEndTime();     // Assume ProfileAnalyzeTimeRange has getEndTime()
                    if (tsTime >= start && tsTime <= end) {
                        snapshots.add(ts);
                        break;
                    }
                }
            } catch (ClassNotFoundException e) {
                // Skip objects that cannot be cast
            } catch (java.io.EOFException eof) {
                break; // End of file reached
            }
        }
    }
    return snapshots;
}

