    } catch (ClassNotFoundException e) {
        throw new IOException("Failed to deserialize ThreadSnapshot objects", e);
    }

    if (snapshots == null || snapshots.isEmpty()) {
        return Collections.emptyList();
    }

    if (timeRanges == null || timeRanges.isEmpty()) {
        return snapshots;
    }

    List<ThreadSnapshot> result = new ArrayList<>();
    for (ThreadSnapshot snapshot : snapshots) {
        long ts = snapshot.getTimestamp(); // assumed method returning epoch millis
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (ts >= range.getStartTime() && ts <= range.getEndTime()) {
                result.add(snapshot);
                break;
            }
        }
    }
    return result;
}
